 ],
 "previous_turns_for_context_only": [],
 "turns": [
  {
   "id": "M1:T1",
   "speaker": "Analyst",
   "act": "open",
   "guide": "Analyst opens the meeting about Gemini (meeting 1 of 1, kickoff)."
  },
  {
   "id": "M1:T2",
   "speaker": "Client",
   "act": "context",
   "guide": "Client gives the project background below, in their own words.",
   "content": [
    {
     "text": "The document defines the operational requirements for Gemini Control System software. It establishes both general criteria and specific functional requirements for software and controls design in the Gemini Project. It is oriented toward the developers of control and data acquisition systems, not toward the science user of the Gemini telescopes.",
     "role": "background"
    }
   ]
  },
  {
   "id": "M1:T3",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'access modes' and asks about it."
  },
  {
   "id": "M1:T4",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "F.Administrative. It is possible to inquire about system utilization, efficiency, etc. using administrative access. No control is available in this mode, only status and scheduling information is accessible. Under no circumstances should administrative access affect the performance of an ongoing observation. It is entirely possible for a single user to be accessing the system through several modes simultaneously. In fact, this is the typical situation with the Telescope Operator, who is often concurrently accessing the system through the observer, monitor, and operator modes. There are times when an astronomer might be using both observer and monitor modes.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T5",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "F.Administrative. It is possible to inquire about system utilization, efficiency, etc. using administrative access. No control is available in this mode, only status and scheduling information is accessible. Under no circumstances should administrative access affect the performance of an ongoing observation. It is entirely possible for a single user to be accessing the system through several modes simultaneously. In fact, this is the typical situation with the Telescope Operator, who is often concurrently accessing the system through the observer, monitor, and operator modes. There are times when an astronomer might be using both observer and monitor modes.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T6",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T7",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'interactive observing' and asks about it."
  },
  {
   "id": "M1:T8",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The initial implementation of the automatic sequencer will operate in a \"pass through\"mode where all commands are accepted and transmitted with minimal checking and delay.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T9",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'remote control' and asks about it."
  },
  {
   "id": "M1:T10",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The philosophy behind this is that, for safety considerations, telescope control commands cannot be issued without a staff member (not necessarily the same person) having direct access to: a hard wired \"stop\" button; real time video and audio; control of the telescope.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T11",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T12",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'remote observing' and asks about it."
  },
  {
   "id": "M1:T13",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Remote users shall normally interact with the system via",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T14",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "via the scheduler program and shall not control any part of the Gemini 8m Telescopes directly.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T15",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T16",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'remote access' and asks about it."
  },
  {
   "id": "M1:T17",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Remote access, in this case, must be possible from the Gemini 8m Telescopes base facility.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T18",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'service' and asks about it."
  },
  {
   "id": "M1:T19",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The observing program must be automated, requiring little human interaction during the observation. The means that the Gemini software must include a sufficiently rich programming environment to make this feasible. In addition, this should be a visually-oriented environment providing a simple, easy-to-use interface to the astronomer.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T20",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  }
 ]
}
